mapper.select:
SELECT 
FROM registration reg
LEFT JOIN runner r ON reg.runner_id = r.id
LEFT JOIN marathon_event e ON reg.event_id = e.id


        AND reg.event_id = #{eventId}


        AND r.name LIKE CONCAT('%', #{name}, '%')


        AND reg.pay_status = #{payStatus}


        AND reg.status = #{status}


ORDER BY reg.id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM registration reg
LEFT JOIN runner r ON reg.runner_id = r.id


        AND reg.event_id = #{eventId}


        AND r.name LIKE CONCAT('%', #{name}, '%')


        AND reg.pay_status = #{payStatus}


        AND reg.status = #{status}

SELECT COUNT(*)
FROM registration reg
INNER JOIN runner r ON reg.runner_id = r.id
WHERE reg.event_id = #{eventId}
  AND reg.status = 1
  AND r.gender = #{gender}

mapper.delete:
DELETE FROM registration
WHERE runner_id = #{runnerId}
  AND NOT EXISTS (
      SELECT 1 FROM `result` res
      WHERE res.registration_id = registration.id
  )

DELETE FROM registration
WHERE event_id = #{eventId}
  AND NOT EXISTS (
      SELECT 1 FROM `result` res
      WHERE res.registration_id = registration.id
  )
